/**
 * @brief Switches between tandem and CW-primary motion.
 *
 * @param checked true = CW-primary
 *
 * @note Motion controller refuses CW-primary until the arm is calibrated, in
 *       which case `HandleMotionModeChanged()` sets the button back.
 */
void MainWindow::on_pb_cw_primary_toggled(bool checked) {
    // WaterController ignores CW commands unless ATC is on
    // TODO: decide whether to block this instead of only warning
    if (checked && !ui_->pb_atc_enable->isChecked()) {
        logger_->Warn("CW-primary needs automatic torque compensation on; "
                      "otherwise the water controller ignores the CW commands");
    }
    emit EnableCwPrimary(checked);
}
